import manifest from './images.json';
import { asset } from '../config/site';

/**
 * Resolves an authored image path (e.g. "/assets/clv-chart.png") to the
 * responsive WebP set generated by `npm run images`.
 *
 * Returns intrinsic width/height as well, so every <img> can reserve its box
 * before the file arrives and the page never jumps as figures load. Paths the
 * manifest does not know fall through untouched.
 */
export const picture = (src, sizes = '100vw') => {
  const entry = manifest[src];
  if (!entry) return { src: asset(src), full: asset(src) };

  const url = (w) => asset(`/assets/${entry.name}-${w}.webp`);
  const largest = entry.widths.at(-1);
  // Fallback for browsers that ignore srcset: the first rung of 800px or more.
  const fallback = entry.widths.find((w) => w >= 800) ?? largest;

  return {
    src: url(fallback),
    srcSet: entry.widths.map((w) => `${url(w)} ${w}w`).join(', '),
    sizes,
    width: entry.width,
    height: entry.height,
    full: url(largest),
  };
};
